  const prices = await pricingApi.getPrices({services:["EC2","RDS","CloudFront"], instance:"t4g.medium"});
  const monthly = prices.ec2 * 730 + prices.rds * 730 + prices.cloudfront * 730;
  return monthly;
}
```

